  background: white;

  /* [!code highlight:4] */
  @variant hover:focus {
    background: black;
  }
}
```

```css
/* [!code filename:Compiled CSS] */
.my-element {
  background: white;

  /* [!code highlight:8] */
  &:hover {
    @media (hover: hover) {
      &:focus {
        background: black;
      }
    }
  }
}
```

</CodeExampleStack>

